const $=s=>document.querySelector(s);const icons={files:'<path d="M3 11V5h16l5 6h21v32H3z"/><path d="M3 15h42v28H3z"/>',notes:'<path d="M9 3h24l8 8v34H9z"/><path d="M33 3v10h8M16 21h18M16 27h18M16 33h12"/>',draw:'<path d="M5 38l27-29 8 8-27 29-10 2zM28 13l8 8M5 38l8 8"/><path d="M4 4h17M4 4v22"/>',terminal:'<rect x="3" y="6" width="42" height="34"/><path d="M3 13h42M10 20l7 6-7 6M23 32h12"/>',settings:'<circle cx="24" cy="24" r="17"/><circle cx="24" cy="24" r="7"/><path d="M24 1v7M24 40v7M1 24h7M40 24h7M7 7l5 5M36 36l5 5M7 41l5-5M36 12l5-5"/>',trash:'<path d="M11 13l3 32h22l3-32M7 12h36M18 12V5h14v7M21 19v19M29 19v19"/>',welcome:'<rect x="4" y="5" width="40" height="32"/><path d="M17 44h14M24 37v7M4 12h40M12 21h7M12 27h22"/>',calc:'<rect x="9" y="3" width="30" height="42"/><path d="M14 9h20v10H14zM15 26h3M23 26h3M31 26h3M15 33h3M23 33h3M31 33h3M15 39h3M23 39h3M31 39h3"/>'};const svg=id=>`<svg viewBox="0 0 48 48" aria-hidden="true">${icons[id]||icons.notes}</svg>`;
const apps={welcome:['Bienvenido.txt',450,426],files:['Explorador',550,340],notes:['Bloc de notas',460,370],draw:['Estudio de dibujo',520,385],terminal:['Terminal',520,345],calc:['Calculadora',285,390],settings:['Configuración',410,350],trash:['Papelera',390,300]};let topZ=10;const opened=new Map();let deleted=false;let storageOK=true;function read(k,f){try{return localStorage.getItem(k)??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,v)}catch{storageOK=false;toast('No se pudo guardar en este navegador.')}}
const iconApps=['files','notes','draw','terminal','settings','trash'];$('#icons').innerHTML=iconApps.map(id=>`<button class="desktop-icon" data-open="${id}">${svg(id)}<span>${apps[id][0]}</span></button>`).join('');$('#startapps').innerHTML=Object.keys(apps).map(id=>`<button data-open="${id}">↗ &nbsp; ${apps[id][0]}</button>`).join('');
function body(id){switch(id){case'welcome':return `<div class="welcome-content"><span class="eyebrow">TU ESCRITORIO. TUS REGLAS.</span><h1>Todo empieza<br>con un <em>clic.</em></h1><p>Un pequeño sistema de ventanas para tus grandes ideas. Explora, escribe, dibuja. Aquí el tiempo va a tu ritmo.</p><div class="welcome-bottom"><button class="primary" data-open="files">Explorar escritorio ↗</button><div class="stamp">✳</div></div></div>`;case'files':return `<div class="file-toolbar">↰ <span class="path">PAPEL / Escritorio</span><span>⊞</span></div><div class="file-grid"><button class="file-item" data-open="notes">${svg('notes')}<span>Ideas.txt</span><small>DOCUMENTO</small></button><button class="file-item" data-open="draw">${svg('draw')}<span>Sin título.png</span><small>ESTUDIO</small></button><button class="file-item" data-open="terminal">${svg('terminal')}<span>Terminal.exe</span><small>APLICACIÓN</small></button><button class="file-item" data-open="calc">${svg('calc')}<span>Calculadora</span><small>UTILIDAD</small></button><button class="file-item" data-open="settings">${svg('settings')}<span>Preferencias</span><small>SISTEMA</small></button>${!deleted?'<button class="file-item" id="deletefile">'+svg('notes')+'<span>Borrador.txt</span><small>CLIC PARA ELIMINAR</small></button>':''}</div>`;case'notes':return '<textarea class="note" aria-label="Escribe tus notas" spellcheck="false"></textarea>';case'draw':return '<div class="drawing"><div class="drawtools"><span>Lápiz</span><input type="color" value="#292a26" aria-label="Color del lápiz"><button id="clearcanvas">Borrar</button><button id="downloadcanvas">Guardar PNG ↗</button></div><canvas width="960" height="500" aria-label="Lienzo de dibujo"></canvas></div>';case'terminal':return '<div class="terminal"><p>PAPEL OS [versión 1.0.26]\nTodo un universo, 0 complicaciones.\n\nEscribe «help» para empezar.</p><div id="terminalout"></div><label>papel:~ $ <input autocomplete="off" spellcheck="false" aria-label="Comando"></label></div>';case'calc':return '<div class="calc"><output>0</output><div class="keys">'+['C','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','⌫','0','.','='].map(k=>`<button data-key="${k}">${k}</button>`).join('')+'</div></div>';case'settings':return '<div class="settings"><h2>A tu manera.</h2><div class="setting-row"><span>Color de acento</span><div class="swatches">'+['#d4ff63','#b7cafa','#f4bda4','#e1c2eb'].map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" aria-label="Acento ${c}"></button>`).join('')+'</div></div><div class="setting-row"><span>Modo orbital ✳</span><button class="switch" id="chaos">Activar / desactivar</button></div><div class="setting-row"><span>Reducir animaciones</span><input type="checkbox" id="motion" aria-label="Reducir animaciones" '+(document.body.classList.contains('reduced')?'checked':'')+'></div><p style="font-size:9px;color:var(--muted)">Tus notas y preferencias se guardan en este navegador.</p></div>';case'trash':return `<div class="empty">${svg('trash')}<h2>${deleted?'Una segunda oportunidad.':'Nada que olvidar.'}</h2><p>${deleted?'Borrador.txt está aquí. ¿Lo recuperamos?':'Tu papelera está vacía.<br>Hasta el desorden necesita un descanso.'}</p>${deleted?'<button class="primary" id="restore">Restaurar Borrador.txt</button>':''}</div>`;}}
function focus(w){w.style.zIndex=++topZ;document.querySelectorAll('.window').forEach(x=>x.classList.toggle('active',x===w));tasks()}
function tasks(){$('#tasks').innerHTML=[...opened].map(([id,w])=>`<button class="task ${w.classList.contains('active')&&!w.hidden?'active':''}" data-task="${id}">${apps[id][0]}</button>`).join('')}
function openApp(id){$('#start').hidden=true;if(opened.has(id)){let w=opened.get(id);w.hidden=false;focus(w);return}const [name,width,height]=apps[id],w=document.createElement('section');w.className='window';w.dataset.app=id;w.setAttribute('aria-label',name);w.style.width=width+'px';w.style.height=height+'px';const mobile=innerWidth<700;w.style.left=(mobile?10:Math.min((innerWidth>1100?330:160)+opened.size*30,innerWidth-width-24))+'px';w.style.top=(mobile?45+opened.size*8:48+opened.size*25)%Math.max(80,innerHeight-350)+'px';w.innerHTML=`<div class="titlebar"><span>▧</span><strong>${name}</strong><span class="grip"></span><div class="controls"><button data-action="min" aria-label="Minimizar">−</button><button data-action="max" aria-label="Maximizar">□</button><button data-action="close" aria-label="Cerrar">×</button></div></div><div class="menubar"><span>PAPEL / ${id==='welcome'?'INICIO':name.toUpperCase()}</span><span>LOCAL</span></div><div class="content">${body(id)}</div><div class="window-status"><span>${id==='notes'?'Guardado automático':'SISTEMA LISTO'}</span><span>↙ ${String(opened.size+1).padStart(2,'0')}</span></div>`;$('#windows').append(w);opened.set(id,w);w.addEventListener('pointerdown',()=>focus(w));focus(w);drag(w);setup(id,w)}
function drag(w){const bar=w.querySelector('.titlebar');bar.ondblclick=e=>{if(!e.target.closest('button'))w.classList.toggle('maximized')};bar.onpointerdown=e=>{if(e.target.closest('button')||w.classList.contains('maximized'))return;const x=e.clientX,y=e.clientY,l=w.offsetLeft,t=w.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=p=>{w.style.left=Math.min(innerWidth-80,Math.max(0,l+p.clientX-x))+'px';w.style.top=Math.max(0,Math.min(innerHeight-130,t+p.clientY-y))+'px'};bar.onpointerup=()=>bar.onpointermove=null;bar.onpointercancel=()=>bar.onpointermove=null}}
function setup(id,w){if(id==='notes'){const t=w.querySelector('textarea');t.value=read('papel-note','Cosas que se me ocurren…\n\n01. Hacer algo por primera vez.\n02. Dibujar sin saber dibujar.\n03. Dejar espacio para lo inesperado.\n');t.oninput=()=>save('papel-note',t.value)}if(id==='terminal'){const inp=w.querySelector('input'),out=w.querySelector('#terminalout');inp.onkeydown=e=>{if(e.key!=='Enter')return;const v=inp.value.trim(),cmd=v.toLowerCase();inp.value='';if(cmd==='clear'){out.replaceChildren();return}let response={help:'help · date · ls · notes · draw · orbit · clear\nPrueba «orbit» para cambiar la atmósfera.',date:new Date().toLocaleString('es-MX'),ls:'Ideas.txt   Sin título.png   Preferencias/',orbit:'Gravedad opcional. Modo orbital alternado.'}[cmd]||'Comando desconocido. Prueba help.';if(cmd==='notes') {openApp('notes');response='Abriendo Bloc de notas…'}if(cmd==='draw'){openApp('draw');response='Abriendo Estudio de dibujo…'}if(cmd==='orbit')document.body.classList.toggle('chaos');const p=document.createElement('p');p.textContent='$ '+v+'\n'+response;out.append(p);inp.scrollIntoView({block:'nearest'})}}if(id==='draw'){const c=w.querySelector('canvas'),ctx=c.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=4;let down=false;const point=e=>{let r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};c.onpointerdown=e=>{down=true;c.setPointerCapture(e.pointerId);ctx.strokeStyle=w.querySelector('input').value;ctx.beginPath();ctx.moveTo(...point(e));ctx.lineTo(...point(e));ctx.stroke()};c.onpointermove=e=>{if(down){ctx.lineTo(...point(e));ctx.stroke()}};c.onpointerup=c.onpointercancel=()=>down=false;w.querySelector('#clearcanvas').onclick=()=>ctx.clearRect(0,0,c.width,c.height);w.querySelector('#downloadcanvas').onclick=()=>{let a=document.createElement('a');a.download='papel-dibujo.png';a.href=c.toDataURL();a.click();toast('Dibujo descargado.')}}if(id==='calc'){let current='0',previous=null,operation=null,fresh=false;const output=w.querySelector('output');function operate(){if(previous===null||!operation)return;let a=Number(previous),b=Number(current);current=String(operation==='+'?a+b:operation==='−'?a-b:operation==='×'?a*b:b===0?'Error':a/b);if(current!=='Error')current=String(Number(Number(current).toPrecision(12)));previous=null;operation=null}w.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{let k=b.dataset.key;if(k==='C'){current='0';previous=null;operation=null}else if(k==='⌫'){current=current.slice(0,-1)||'0'}else if(k==='±')current=String(-Number(current));else if(k==='%')current=String(Number(current)/100);else if(['+','−','×','÷'].includes(k)){operate();previous=current;operation=k;fresh=true}else if(k==='='){operate();fresh=true}else{if(fresh||current==='Error'){current='0';fresh=false}if(k==='.'&&current.includes('.'))return;current=current==='0'&&k!=='.'?k:current+k}output.textContent=current})}}
function refresh(id){let w=opened.get(id);if(w){w.querySelector('.content').innerHTML=body(id);setup(id,w)}}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
document.addEventListener('click',e=>{let a=e.target.closest('[data-open]');if(a)openApp(a.dataset.open);let task=e.target.closest('[data-task]');if(task){let w=opened.get(task.dataset.task);if(!w.hidden&&w.classList.contains('active')){w.hidden=true;tasks()}else{w.hidden=false;focus(w)}}let control=e.target.closest('[data-action]');if(control){let w=control.closest('.window'),id=w.dataset.app;if(control.dataset.action==='max')w.classList.toggle('maximized');if(control.dataset.action==='close'){w.classList.add('closing');setTimeout(()=>{w.remove();opened.delete(id);tasks()},240)}if(control.dataset.action==='min'){w.classList.add('minimizing');setTimeout(()=>{w.hidden=true;w.classList.remove('minimizing');tasks()},280)}}let sw=e.target.closest('[data-color]');if(sw){document.documentElement.style.setProperty('--accent',sw.dataset.color);save('papel-accent',sw.dataset.color)}if(e.target.id==='chaos'){document.body.classList.toggle('chaos');toast('Modo orbital '+(document.body.classList.contains('chaos')?'activado ✳':'desactivado'))}if(e.target.id==='motion'){document.body.classList.toggle('reduced',e.target.checked);save('papel-motion',e.target.checked?'1':'0')}if(e.target.closest('#deletefile')){deleted=true;refresh('files');refresh('trash');toast('Borrador.txt se movió a la papelera.')}if(e.target.id==='restore'){deleted=false;refresh('files');refresh('trash');toast('Archivo restaurado.')}if(!e.target.closest('#start')&&!e.target.closest('#startbutton')&&!e.target.closest('#brand'))$('#start').hidden=true});
$('#startbutton').onclick=$('#brand').onclick=()=>$('#start').hidden=!$('#start').hidden;$('#showdesktop').onclick=()=>{let hide=[...opened.values()].some(w=>!w.hidden);opened.forEach(w=>w.hidden=hide);tasks()};$('#cascade').onclick=()=>opened.forEach((w,id)=>{w.hidden=false;w.classList.remove('maximized');w.style.left=(innerWidth<700?10:140+([...opened.keys()].indexOf(id)%5)*35)+'px';w.style.top=(25+([...opened.keys()].indexOf(id)%5)*30)+'px'});$('#reboot').onclick=()=>{opened.forEach(w=>w.remove());opened.clear();tasks();$('#start').hidden=true;boot()};function tick(){$('#clock').textContent=new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit',hour12:false});$('time').textContent=new Date().toLocaleDateString('es-MX',{day:'2-digit',month:'short'}).toUpperCase()}tick();setInterval(tick,1000);document.documentElement.style.setProperty('--accent',read('papel-accent','#2466da'));document.body.classList.toggle('reduced',read('papel-motion','0')==='1');function boot(){$('#boot').classList.remove('done');setTimeout(()=>{$('#boot').classList.add('done');openApp('welcome')},1700)}boot();document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#start').hidden=true});
